package com.supersports.fulfillment;import java.util.Map;import java.util.UUID;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/v1/internal/checkout/fulfillment") class FulfillmentController{private final FulfillmentRepository repo;FulfillmentController(FulfillmentRepository repo){this.repo=repo;}@PostMapping Map<String,Object> schedule(@RequestBody Request r){try{return repo.schedule(UUID.fromString(r.orderId()),r.fence(),r.operationKey());}catch(FulfillmentRepository.StaleFenceException e){throw new ResponseStatusException(HttpStatus.CONFLICT,"Stale checkout fence");}catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,e.getMessage());}catch(IllegalStateException e){throw new ResponseStatusException(HttpStatus.CONFLICT,"Operation key conflict");}}@GetMapping("/{orderId}")Map<String,Object>status(@PathVariable UUID orderId){return repo.status(orderId);}record Request(String orderId,long fence,String operationKey){}}
